using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;public class DamageArrow : MonoBehaviour{	private void OnTriggerEnter(Collider other)	{		if (other.gameObject.tag == "Player")		{
			GameObject.FindGameObjectWithTag("DamageArrowImage").GetComponent<Image>().enabled = true;			ScoreManager.score += 15;			other.gameObject.GetComponentInChildren<PlayerShooting>().ApplyMoreDamage(40);			Destroy(this.gameObject);		}	}}